//! The geometry and the names the model and the cell simulator share.
//!
//! The static scene (table, feeder, arena, tower base, pads, gripper) is in
//! `shared_folder/scenario`, generated by `tools/generate_scene.py`. The numbers
//! here mirror the ones in that script - change one, change the other.

use nalgebra::{Matrix3, Rotation3, Unit, UnitQuaternion, Vector3};

pub const MAX_DICE: usize = 6;
pub const MAX_PADS: usize = 3;

/// Edge length of a die, metres.
pub const DIE: f64 = 0.04;
/// Inner half-size of the arena tray.
pub const ARENA_INNER_HALF: f64 = 0.13;
/// Height of a die's centre above the arena frame when it lies on the floor.
pub const ARENA_DIE_Z: f64 = 0.005 + DIE / 2.0;
/// How far a landed die keeps from the walls: far enough that the fingers,
/// which reach 35 mm from the die's centre, close on it without touching a wall.
pub const ARENA_MARGIN: f64 = 0.047;
/// How far apart landed dice keep, centre to centre, if there is room: a die plus
/// the fingers on both sides of it.
pub const ARENA_SPACING: f64 = 0.08;
/// The TCP's height while it travels between two places - above a full tower.
/// Mirrors SAFE_Z in tools/generate_scene.py.
pub const SAFE_Z: f64 = 0.34;

/// One die: its id (the colour), how it is drawn, and the colour of its pips.
pub struct DieColour {
    pub name: &'static str,
    pub rgb: [f64; 3],
    pub pips: [f64; 3],
}

const WHITE: [f64; 3] = [0.97, 0.97, 0.95];
const BLACK: [f64; 3] = [0.05, 0.05, 0.06];

/// The dice, in the order N_DICE takes them.
pub const DIE_COLOURS: [DieColour; MAX_DICE] = [
    DieColour { name: "red", rgb: [0.86, 0.12, 0.12], pips: WHITE },
    DieColour { name: "green", rgb: [0.10, 0.62, 0.25], pips: WHITE },
    DieColour { name: "blue", rgb: [0.12, 0.32, 0.86], pips: WHITE },
    DieColour { name: "yellow", rgb: [0.98, 0.82, 0.10], pips: BLACK },
    DieColour { name: "purple", rgb: [0.52, 0.22, 0.74], pips: WHITE },
    DieColour { name: "orange", rgb: [1.00, 0.48, 0.05], pips: WHITE },
];

pub fn die_colour(name: &str) -> Option<&'static DieColour> {
    DIE_COLOURS.iter().find(|c| c.name == name)
}

// --- Frame names ----------------------------------------------------------------

/// The frame a die's pose lives in: its centre, z up, yawed however it landed.
/// This is the frame the robot goes to when it picks the die.
pub fn die_frame(die: &str) -> String {
    format!("{die}_die")
}
/// Child of [`die_frame`]: turned so that the face showing is the one up.
pub fn die_body_frame(die: &str) -> String {
    format!("{die}_die_body")
}
pub fn die_pips_frame(die: &str) -> String {
    format!("{die}_die_pips")
}
pub fn level_frame(level: usize) -> String {
    format!("level_{level}")
}
pub fn pad_frame(pad: usize) -> String {
    format!("pad_{pad}")
}
pub fn feeder_slot_frame(slot: usize) -> String {
    format!("feeder_slot_{slot}")
}
pub const ARENA_FRAME: &str = "arena";
pub const ARENA_DROP_FRAME: &str = "arena_drop";
/// Where a die sits on the flip station, upright.
pub const FLIP_STATION_FRAME: &str = "flip_station";
/// The TCP pose that sets a die down on the flip station on its side.
pub const FLIP_STATION_TILT_FRAME: &str = "flip_station_tilt";
pub const FLIP_STATION_TILT_ABOVE_FRAME: &str = "flip_station_tilt_above";
/// Published by the cell when a flip is planned: where to grip the die so that
/// the face that should come up faces the right way in the gripper.
pub const FLIP_GRIP_FRAME: &str = "flip_grip";
/// Published by the cell when a flip is planned: where the flipped die is put
/// back down in the arena.
pub const FLIP_RETURN_FRAME: &str = "flip_return";
pub const TCP_FRAME: &str = "gripper_tcp";
pub const TCP_ABOVE_FRAME: &str = "gripper_tcp_above";
pub const WORLD_FRAME: &str = "world";

/// The point at [`SAFE_Z`] straight above `frame`, turned the same way about the
/// vertical. Every transfer arrives at and leaves a place through it. Static
/// for the fixed places (in the scene); for a loose die and the flip frames the
/// cell publishes it whenever the die comes to rest.
pub fn transit_frame(frame: &str) -> String {
    format!("{frame}_transit")
}

// --- Faces ------------------------------------------------------------------------

/// The rotation of a die's body that puts `face` on top.
///
/// The die mesh has 1 on +z, 6 on -z, 2 on +x, 5 on -x, 3 on +y and 4 on -y
/// (opposite faces add up to seven) - see FACE_NORMALS in
/// tools/generate_scene.py.
pub fn face_up_rotation(face: i64) -> UnitQuaternion<f64> {
    let x = Vector3::x_axis();
    let y = Vector3::y_axis();
    let half_pi = std::f64::consts::FRAC_PI_2;
    match face {
        1 => UnitQuaternion::identity(),
        6 => UnitQuaternion::from_axis_angle(&x, std::f64::consts::PI),
        2 => UnitQuaternion::from_axis_angle(&y, -half_pi),
        5 => UnitQuaternion::from_axis_angle(&y, half_pi),
        3 => UnitQuaternion::from_axis_angle(&x, half_pi),
        4 => UnitQuaternion::from_axis_angle(&x, -half_pi),
        _ => UnitQuaternion::identity(),
    }
}

/// Which way `face` points in the die's own frame.
pub fn face_normal(face: i64) -> Vector3<f64> {
    match face {
        1 => Vector3::new(0.0, 0.0, 1.0),
        6 => Vector3::new(0.0, 0.0, -1.0),
        2 => Vector3::new(1.0, 0.0, 0.0),
        5 => Vector3::new(-1.0, 0.0, 0.0),
        3 => Vector3::new(0.0, 1.0, 0.0),
        _ => Vector3::new(0.0, -1.0, 0.0),
    }
}

/// The 24 ways a die can lie square: a face up, turned in quarter steps.
pub fn aligned_rotations() -> Vec<UnitQuaternion<f64>> {
    let half_pi = std::f64::consts::FRAC_PI_2;
    let mut all = vec![];
    for face in 1..=6 {
        for quarter in 0..4 {
            all.push(yaw(quarter as f64 * half_pi) * face_up_rotation(face));
        }
    }
    all
}

/// The square orientation nearest `rotation`. A die's orientation is always
/// one of the 24, but the arm only gets within a fraction of a degree of its
/// targets, so what comes back from it is snapped.
pub fn snap_to_aligned(rotation: &UnitQuaternion<f64>) -> UnitQuaternion<f64> {
    aligned_rotations()
        .into_iter()
        .max_by(|a, b| a.coords.dot(&rotation.coords).abs().total_cmp(&b.coords.dot(&rotation.coords).abs()))
        .unwrap()
}

/// Whether `rotation` turns every axis onto an axis.
pub fn is_aligned(rotation: &UnitQuaternion<f64>) -> bool {
    let m: Matrix3<f64> = Rotation3::from(*rotation).into_inner();
    m.iter().all(|v| (v.abs() - 1.0).abs() < 1e-6 || v.abs() < 1e-6)
}

/// Which face points up for a body rotated by `rotation` - the camera's job.
pub fn face_showing(rotation: &UnitQuaternion<f64>) -> i64 {
    let normals: [(i64, Vector3<f64>); 6] = [
        (1, Vector3::new(0.0, 0.0, 1.0)),
        (6, Vector3::new(0.0, 0.0, -1.0)),
        (2, Vector3::new(1.0, 0.0, 0.0)),
        (5, Vector3::new(-1.0, 0.0, 0.0)),
        (3, Vector3::new(0.0, 1.0, 0.0)),
        (4, Vector3::new(0.0, -1.0, 0.0)),
    ];
    normals
        .iter()
        .map(|(face, n)| (*face, (rotation * n).z))
        .fold((0, f64::MIN), |best, (face, up)| if up > best.1 { (face, up) } else { best })
        .0
}

pub fn yaw(angle: f64) -> UnitQuaternion<f64> {
    UnitQuaternion::from_axis_angle(&Unit::new_normalize(Vector3::z()), angle)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn there_are_24_square_orientations_and_snapping_finds_them() {
        let all = aligned_rotations();
        assert_eq!(all.len(), 24);
        for (i, a) in all.iter().enumerate() {
            assert!(is_aligned(a));
            for b in &all[i + 1..] {
                assert!(a.angle_to(b) > 0.1, "duplicate orientation");
            }
            let nudged = a * UnitQuaternion::from_euler_angles(0.01, -0.02, 0.015);
            assert!(snap_to_aligned(&nudged).angle_to(a) < 1e-9);
        }
    }

    #[test]
    fn every_face_up_rotation_shows_its_face() {
        for face in 1..=6 {
            assert_eq!(face_showing(&face_up_rotation(face)), face);
            // Spinning the die about the vertical does not change what is on top.
            assert_eq!(face_showing(&(yaw(0.7) * face_up_rotation(face))), face);
        }
    }
}
